    'plugins': ['git_manager','test_runner','lifecycle_manager','obsidian_brain'],
    'hooks': ['pre_decomposition','post_task','pre_commit','post_commit'],
    'skills': ['disambiguation','spec_writer','tdd_orchestrator','macro_reviewer'],
